1: // 纯 JS AES-256-CBC + PKCS5(PKCS7) 加密，输出 base64。
2: // 与后端 com.zhishu.common.core.utils.AESUtil 对齐：
3: //   key = 'A-16-Byte-keyValA-16-Byte-keyVal' (32字节 => AES-256)
4: //   iv  = 'A-16-Byte-String' (16字节)
5: // 仅实现加密（登录密码用），解密可选。
6: 
7: type Word = number[]
8: const SBOX: number[] = []
9: const INV_SBOX: number[] = []
10: const RCON: number[] = []
11: ;(function initTables() {
12:   // 生成 S-box（基于 GF(2^8) 乘法逆 + 仿射变换），避免手抄 256 项
13:   const p = new Uint8Array(256)
14:   const q = new Uint8Array(256)
15:   let x = 1
16:   for (let i = 0; i < 255; i++) {
17:     p[i] = x
18:     // x * 3 in GF(2^8)
19:     x ^= (x << 1) ^ (x & 0x80 ? 0x1b : 0)
20:     x &= 0xff
21:     // q[i] = x^-1 track via p; we build log/antilog
22:   }
23:   // 用对数表构造逆
24:   const log = new Uint8Array(256)
25:   const exp = new Uint8Array(256)
26:   let expx = 1
27:   for (let i = 0; i < 255; i++) {
28:     exp[i] = expx
29:     log[expx] = i
30:     // expx *= 3
31:     expx ^= (expx << 1) ^ (expx & 0x80 ? 0x1b : 0)
32:     expx &= 0xff
33:   }
34:   exp[255] = exp[0]
35:   for (let i = 2; i < 256; i++) {
36:     const inv = exp[(255 - log[i]) % 255]
37:     let s = inv
38:     let s2 = ((s << 1) | (s >> 7)) & 0xff
39:     let s3 = ((s2 << 1) | (s2 >> 7)) & 0xff
40:     let s4 = ((s3 << 1) | (s3 >> 7)) & 0xff
41:     let s5 = ((s4 << 1) | (s4 >> 7)) & 0xff
42:     let r = s ^ s2 ^ s3 ^ s4 ^ s5 ^ 0x63
43:     SBOX[i] = r & 0xff
44:     INV_SBOX[r & 0xff] = i
45:   }
46:   SBOX[0] = 0x63
47:   INV_SBOX[0x63] = 0
48:   let rcon = 1
49:   for (let i = 0; i < 15; i++) { RCON[i] = rcon; rcon = gmul(rcon, 2) }
50: })()
