52: function gmul(a: number, b: number): number {
53:   let p = 0
54:   for (let i = 0; i < 8; i++) {
55:     if (b & 1) p ^= a
56:     const hi = a & 0x80
57:     a = (a << 1) & 0xff
58:     if (hi) a ^= 0x1b
59:     b >>= 1
60:   }
61:   return p & 0xff
62: }
