64: function xtime(a: number): number { return ((a << 1) ^ (a & 0x80 ? 0x1b : 0)) & 0xff }
65: 
66: function expandKey(key: number[]): number[][] {
67:   const Nk = key.length / 4 // 8 for 256
68:   const Nr = Nk + 6 // 14 for 256
69:   const w: number[][] = []
70:   for (let i = 0; i < Nk; i++) w[i] = [key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]
71:   for (let i = Nk; i < 4 * (Nr + 1); i++) {
72:     let temp = w[i - 1].slice()
73:     if (i % Nk === 0) {
74:       temp = [temp[1], temp[2], temp[3], temp[0]] // RotWord
75:       temp = temp.map(b => SBOX[b]) // SubWord
76:       temp[0] ^= RCON[i / Nk - 1]
77:     } else if (Nk > 6 && i % Nk === 4) {
78:       temp = temp.map(b => SBOX[b])
79:     }
80:     w[i] = w[i - Nk].map((b, j) => b ^ temp[j])
81:   }
82:   const roundKeys: number[][] = []
83:   for (let r = 0; r <= Nr; r++) {
84:     const rk: number[] = []
85:     for (let c = 0; c < 4; c++) rk.push(...w[4 * r + c])
86:     roundKeys.push(rk)
87:   }
88:   return roundKeys
89: }
