91: function addRoundKey(state: number[], rk: number[]) { for (let i = 0; i < 16; i++) state[i] ^= rk[i] }
92: 
93: function subBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]] }
94: function invSubBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = INV_SBOX[state[i]] }
