96: function shiftRows(s: number[]) {
97:   // 列主序：state[c*4+r]
98:   for (let r = 1; r < 4; r++) {
99:     const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
100:     const sh = row.slice(r).concat(row.slice(0, r))
101:     s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
102:   }
103: }
104: function invShiftRows(s: number[]) {
105:   for (let r = 1; r < 4; r++) {
106:     const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
107:     const sh = row.slice(4 - r).concat(row.slice(0, 4 - r))
108:     s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
109:   }
110: }
111: function mixColumns(s: number[]) {
112:   for (let c = 0; c < 4; c++) {
113:     const i = 4 * c
114:     const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
115:     s[i] = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3
116:     s[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3
117:     s[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3)
118:     s[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2)
119:   }
120: }
121: function invMixColumns(s: number[]) {
122:   for (let c = 0; c < 4; c++) {
123:     const i = 4 * c
124:     const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
125:     s[i] = gmul(a0, 14) ^ gmul(a1, 11) ^ gmul(a2, 13) ^ gmul(a3, 9)
126:     s[i + 1] = gmul(a0, 9) ^ gmul(a1, 14) ^ gmul(a2, 11) ^ gmul(a3, 13)
127:     s[i + 2] = gmul(a0, 13) ^ gmul(a1, 9) ^ gmul(a2, 14) ^ gmul(a3, 11)
128:     s[i + 3] = gmul(a0, 11) ^ gmul(a1, 13) ^ gmul(a2, 9) ^ gmul(a3, 14)
129:   }
130: }
