132: function encryptBlock(input: number[], roundKeys: number[][]): number[] {
133:   const s = input.slice()
134:   addRoundKey(s, roundKeys[0])
135:   const Nr = roundKeys.length - 1
136:   for (let r = 1; r < Nr; r++) {
137:     subBytes(s); shiftRows(s); mixColumns(s); addRoundKey(s, roundKeys[r])
138:   }
139:   subBytes(s); shiftRows(s); addRoundKey(s, roundKeys[Nr])
140:   return s
141: }
142: function decryptBlock(input: number[], roundKeys: number[][]): number[] {
143:   const s = input.slice()
144:   const Nr = roundKeys.length - 1
145:   addRoundKey(s, roundKeys[Nr])
146:   for (let r = Nr - 1; r >= 1; r--) {
147:     invShiftRows(s); invSubBytes(s); addRoundKey(s, roundKeys[r]); invMixColumns(s)
148:   }
149:   invShiftRows(s); invSubBytes(s); addRoundKey(s, roundKeys[0])
