// 统一门户 APP 端登录接口封装（v3.0）
// 文档：统一门户APP端登录接口文档 v1.0.0（禅道 1431）
// 网关前缀 /v3.0（经同源 /api 反代）。
//
// 两层令牌模型：
//   1) 门户会话 token：登录后签发，长效复用，存本地，后续接口 Authorization: Bearer
//   2) SSO 跳转 ticket：每次跳子系统现取（/sso/jump），60 秒一次性，禁止缓存跳转地址
import { uniTransport } from './request'

/** 统一响应包裹 { code, msg, data }，code=200 成功 */
interface Envelope<T> { code: number; msg: string; data: T }

/** 计算 portal 接口基础前缀：VITE_API_BASE_URL(/api) + /v3.0 */
function portalBase(): string {
  const env = import.meta.env as Record<string, string | undefined>
  const apiBase = (env.VITE_API_BASE_URL ?? env.VITE_AUTH_BASE_URL ?? '/api').replace(/\/$/, '')
  return `${apiBase}/v3.0`
}

function authHeader(token?: string): Record<string, string> {
  const header: Record<string, string> = { 'Content-Type': 'application/json' }
  if (token) header.Authorization = `Bearer ${token}`
  return header
}

/**
 * 调用 portal 接口并解包。
 * - 网络层超时/5xx：按文档可重试（此处不内建重试，由调用方决定，业务错误不重试）。
 * - 业务错误 code≠200：抛 Error(msg)，msg 为可直接展示的中文提示。
 */
async function portalRequest<T>(
  path: string,
  options: { method?: 'GET' | 'POST'; data?: unknown; token?: string } = {},
): Promise<T> {
  const response = await uniTransport({
    url: `${portalBase()}/${path.replace(/^\//, '')}`,
    method: options.method ?? 'POST',
    data: options.data,
    header: authHeader(options.token),
    timeout: 20000,
  })
  if (response.statusCode === 401) throw new Error('登录已失效，请重新登录')
  if (response.statusCode < 200 || response.statusCode >= 300) {
    const body = response.data as Envelope<unknown> | undefined
    const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
    throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
  }
  const body = response.data as Envelope<T>
  if (body && typeof body === 'object' && 'code' in body) {
    if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
    return body.data
  }
  return response.data as T
}

// ===== 2.1 获取图形验证码 =====
export interface CaptchaResult { uuid: string; imageDataUrl: string }

export async function fetchAppLoginCaptcha(): Promise<CaptchaResult> {
  const data = await portalRequest<{ uuid: string; img: string }>('portal/appLogin/captcha')
  const raw = String(data?.img ?? '')
  const imageDataUrl = raw.startsWith('data:') ? raw : `data:image/jpeg;base64,${raw}`
  return { uuid: String(data?.uuid ?? ''), imageDataUrl }
}

// ===== 2.2 发送短信验证码 =====
export interface SendSmsParams { phone: string; captchaUuid: string; captchaCode: string }

export async function sendAppLoginSms(params: SendSmsParams): Promise<void> {
  await portalRequest<boolean>('portal/appLogin/sms', {
    data: {
      phone: params.phone,
      captchaUuid: params.captchaUuid,
      captchaCode: params.captchaCode,
    },
  })
}

// ===== 2.3 三重校验登录 =====
export interface AppLoginParams { phone: string; idNumberSuffix: string; smsCode: string }
export interface AppLoginResult {
  token: string
  expireTime: string
  userId: string
  userName: string
  nickName: string
}

export async function appLogin(params: AppLoginParams): Promise<AppLoginResult> {
  const data = await portalRequest<AppLoginResult>('portal/appLogin/login', {
    data: {
      phone: params.phone,
      idNumberSuffix: params.idNumberSuffix,
      smsCode: params.smsCode,
    },
  })
  if (!data?.token) throw new Error('登录失败：未获取到令牌')
  return { ...data, userId: String(data.userId) }
}

// ===== 2.4 子系统列表 =====
export interface PortalApp {
  appId: string
  appName: string
  appLogo: string
  authorized: boolean
}

export async function fetchPortalApps(token: string): Promise<PortalApp[]> {
  const data = await portalRequest<PortalApp[]>('portal/appLogin/apps', { token })
  return Array.isArray(data) ? data : []
}

// ===== 2.5 跳转子系统（换一次性票据） =====
/** 返回带票据的跳转地址；每次跳转必须重新调用，禁止缓存 redirectUrl。 */
export async function jumpToPortalApp(appId: string, token: string): Promise<string> {
  const data = await portalRequest<{ redirectUrl: string }>('portal/sso/jump', {
    data: { appId, token },
    token,
  })
  if (!data?.redirectUrl) throw new Error('跳转失败：未获取到跳转地址')
  return data.redirectUrl
}

import { defineStore } from 'pinia'
import { ref } from 'vue'
import { authRequest, setToken, clearToken, getToken } from '../utils/request'
import { aesEncrypt } from '../utils/aes'
import { appLogin, type AppLoginParams, type AppLoginResult } from '../utils/portalAuth'

const USER_KEY = 'portal-user-v1'

export interface PortalUser {
  userId: string
  userName: string
  nickName: string
  expireTime: string
}

function readUser(): PortalUser | undefined {
  try {
    const raw = uni.getStorageSync(USER_KEY)
    if (!raw) return undefined
    return typeof raw === 'string' ? (JSON.parse(raw) as PortalUser) : (raw as PortalUser)
  } catch {
    return undefined
  }
}

function writeUser(user: PortalUser | undefined) {
  try {
    if (user) uni.setStorageSync(USER_KEY, JSON.stringify(user))
    else uni.removeStorageSync(USER_KEY)
  } catch {
    /* ignore */
  }
}

export const useAuthStore = defineStore('portal-auth', () => {
  /** 当前登录用户（从本地安全存储恢复） */
  const currentUser = ref<PortalUser | undefined>(readUser())

  /**
   * 统一门户 APP 端三重校验登录：手机号 + 身份证后 4 位 + 短信验证码。
   * 登录成功后保存门户会话 token 与用户信息。
   */
  async function appLoginAction(params: AppLoginParams): Promise<AppLoginResult> {
    const data = await appLogin(params)
    setToken(data.token)
    const user: PortalUser = {
      userId: data.userId,
      userName: data.userName,
      nickName: data.nickName,
      expireTime: data.expireTime,
    }
    currentUser.value = user
    writeUser(user)
    return data
  }

  /** 旧版账号密码登录（保留兼容；当前门户改用 APP 三重校验登录） */
  async function login(username: string, password: string, captcha?: { code: string; uuid: string }): Promise<void> {
    const encrypted = aesEncrypt(password)
    const payload: Record<string, string> = { username, password: encrypted }
    if (captcha?.code && captcha.uuid) {
      payload.code = captcha.code
      payload.uuid = captcha.uuid
    }
    const res = await authRequest<{ accessToken?: string; token?: string }>('/v2.0/security/auth/login', {
      method: 'POST',
      data: payload,
      token: false,
      raw: true,
    })
    const body = res as unknown as { code?: number; msg?: string; data?: { accessToken?: string; token?: string } }
    if (body && typeof body === 'object' && 'code' in body && body.code !== 200) throw new Error(body.msg || '登录失败')
    const token = body?.data?.accessToken ?? body?.data?.token
    if (!token) throw new Error('登录失败：未获取到令牌')
    setToken(token)
  }

  function logout(): void {
    clearToken()
    writeUser(undefined)
    currentUser.value = undefined
  }

  function isLoggedIn(): boolean {
    return Boolean(getToken())
  }

  return { currentUser, appLoginAction, login, logout, isLoggedIn }
})

